using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);

/// <summary>A real HTTP server standing in for the payment provider.</summary>
public sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Task loop;

    public FakeProvider(int status, string? body)
    {
        var port = FreePort();
        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"http://127.0.0.1:{port}/");
        listener.Start();
        loop = Task.Run(async () =>
        {
            while (listener.IsListening)
            {
                HttpListenerContext ctx;
                try { ctx = await listener.GetContextAsync(); }
                catch (Exception) { return; }

                using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
                Received.Add(new CapturedRequest(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath,
                    ctx.Request.ContentType, await reader.ReadToEndAsync()));

                ctx.Response.StatusCode = status;
                if (body is not null)
                {
                    ctx.Response.ContentType = "application/json";
                    var bytes = Encoding.UTF8.GetBytes(body);
                    await ctx.Response.OutputStream.WriteAsync(bytes);
                }
                ctx.Response.Close();
            }
        });
    }

    public Uri BaseAddress { get; }

    public List<CapturedRequest> Received { get; } = [];

    private static int FreePort()
    {
        var l = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        l.Start();
        var port = ((IPEndPoint)l.LocalEndpoint).Port;
        l.Stop();
        return port;
    }

    public void Dispose()
    {
        listener.Close();
        loop.Wait(TimeSpan.FromSeconds(5));
    }
}
