using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProvider Provider)> Authorize(int status, string? body)
    {
        var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        return (outcome, provider);
    }

    [Fact]
    public async Task The_authorization_is_posted_to_the_provider_with_the_expected_json()
    {
        var (_, provider) = await Authorize(200, """{"status":"approved"}""");
        using var _p = provider;

        var request = Assert.Single(provider.Received);
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);

        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, provider) = await Authorize(200, """{"status":"approved"}""");
        using var _p = provider;
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, provider) = await Authorize(200, """{"status":"declined"}""");
        using var _p = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, provider) = await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        using var _p = provider;
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline_not_an_error()
    {
        var (outcome, provider) = await Authorize(402, """{"error":"card_refused"}""");
        using var _p = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_without_a_body_is_still_a_decline()
    {
        var (outcome, provider) = await Authorize(402, null);
        using var _p = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_surface_as_errors_instead_of_decisions(int status)
    {
        using var provider = new FakeProvider(status, """{"status":"approved"}""");
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var gateway = new HttpPaymentGateway(client);

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            gateway.AuthorizeAsync("ORD-7", new Money(1m, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task A_malformed_answer_is_an_error()
    {
        using var provider = new FakeProvider(200, "not json");
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var gateway = new HttpPaymentGateway(client);

        await Assert.ThrowsAsync<JsonException>(() =>
            gateway.AuthorizeAsync("ORD-7", new Money(1m, "EUR"), CancellationToken.None));
    }

    [Fact]
    public async Task An_unrecognised_status_is_never_treated_as_approved()
    {
        var (outcome, provider) = await Authorize(200, """{"state":"approved"}""");
        using var _p = provider;
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }
}
